questionvariables.text:
/* Design: classify quantities as vector or scalar; two categories in a fixed order, so the correct category is first for some items. Item 5 is kept in the pool but used in no set. Source: original. */
cats: ["s","s","s","s","s","s","s","s","s","s","v","v","v","v","v","v","v","v"];
/* kind: 1 mass, 2 speed, 3 distance, 4 weight, 5 velocity, 6 displacement, 7 plain scalar, 8 plain vector */
kinds: [1,2,3,7,7,7,7,2,3,1,5,6,4,8,5,8,6,4];
sets: [[13,14,6,11],[7,14,8,3],[9,13,8,17],[12,16,2,6],[8,15,14,2],[4,11,15,16],[7,11,8,15],[17,1,18,7],[17,10,16,8],[1,6,16,11]];
ix: 1+rand(10);
S: sets[ix];
it1: S[1]; c1: cats[it1]; kd1: kinds[it1];
opt1: [["vec1", is(c1="v"), "a vector quantity"], ["sca1", is(c1="s"), "a scalar quantity"]];
ta1: first(mcq_correct(opt1)); isv1: is(c1="v");
wr1: if c1="v" then "sca1" else "vec1";
it2: S[2]; c2: cats[it2]; kd2: kinds[it2];
opt2: [["vec2", is(c2="v"), "a vector quantity"], ["sca2", is(c2="s"), "a scalar quantity"]];
ta2: first(mcq_correct(opt2)); isv2: is(c2="v");
wr2: if c2="v" then "sca2" else "vec2";
it3: S[3]; c3: cats[it3]; kd3: kinds[it3];
opt3: [["vec3", is(c3="v"), "a vector quantity"], ["sca3", is(c3="s"), "a scalar quantity"]];
ta3: first(mcq_correct(opt3)); isv3: is(c3="v");
wr3: if c3="v" then "sca3" else "vec3";
it4: S[4]; c4: cats[it4]; kd4: kinds[it4];
opt4: [["vec4", is(c4="v"), "a vector quantity"], ["sca4", is(c4="s"), "a scalar quantity"]];
ta4: first(mcq_correct(opt4)); isv4: is(c4="v");
wr4: if c4="v" then "sca4" else "vec4";
